import sys

def is_palindrome(s):
    return s == s[::-1]

def max_palindromic_concatenation(a, b):
    best = ""
    for i in range(len(a)):
        for j in range(i + 1, len(a) + 1):
            sa = a[i:j]
            if len(sa) > len(best) // 2:
                for k in range(len(b)):
                    for l in range(k + 1, len(b) + 1):
                        sb = b[k:l]
                        candidate = sa + sb
                        if is_palindrome(candidate):
                            if len(candidate) > len(best) or (len(candidate) == len(best) and candidate < best):
                                best = candidate
    return best if best else "-1"

def main():
    import sys
    input = sys.stdin.read().splitlines()
    q = int(input[0])
    a_strings = input[1::2]
    b_strings = input[2::2]
    results = []
    for a, b in zip(a_strings, b_strings):
        results.append(max_palindromic_concatenation(a, b))
    print("\n".join(results))

main()
